package com.fitness.tracker.service; import com.fitness.tracker.entity.User; import com.fitness.tracker.repository.UserRepository; import com.fitness.tracker.exception.ApiExceptionHandler.NotFoundException; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; @Service public class CurrentUserService {private final UserRepository repo; public CurrentUserService(UserRepository r){repo=r;} public User get(Authentication a){return repo.findByEmail(a.getName()).orElseThrow(()->new NotFoundException("User not found"));}}
